int attach_usb_serial(struct usb_serial *serial)
{
    if (serial->num_ports < 2 || serial->port[0].bulk_out_endpointAddr == 0 ||
        serial->port[1].bulk_out_endpointAddr == 0) {
        dev_err(&serial->dev, "Insufficient bulk out endpoints for attachment\n");
        return -ENODEV;
    }

    serial->port[0].bulk_out_endpointAddr = serial->port[1].bulk_out_endpointAddr;
    serial->port[0].bulk_out_size = 0;

    usb_fill_int_urb(serial->port[0].write_urb,
                     serial->dev,
                     usb_sndbulkpipe(serial->dev,
                                     serial->port[0].bulk_out_endpointAddr),
                     serial->port[0].write_urb->transfer_buffer,
                     serial->port[0].write_urb->transfer_buffer_length,
                     serial->port[0].write_urb->complete,
                     serial->port[0].write_urb->context,
                     serial->port[0].bulk_out_interval);

    return 0;
}

int attach_usb_serial(struct usb_serial *serial)
{
    if (serial->num_bulk_out < 2) {
        dev_err(&serial->dev, "Insufficient bulk out endpoints\n");
        return -ENODEV;
    }

    serial->port[0].bulk_out_endpointAddress =
        serial->port[1].bulk_out_endpointAddress;
    serial->port[0].write_urb->pipe = usb_sndbulkpipe(serial->dev,
                                                      serial->port[0].bulk_out_endpointAddress);
    return 0;
}

